// The taskbar of a desktop from 1998, below the scene it wraps. Start opens the
// scene list, the sunken button is the scene showing, Control Panel opens its
// settings, and the tray has the signal, the battery and the clock.
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'

function clock(now, twentyFour) {
  const minutes = pad(now.getMinutes())
  if (twentyFour) return `${pad(now.getHours())}:${minutes}`
  return `${now.getHours() % 12 || 12}:${minutes} ${now.getHours() < 12 ? 'AM' : 'PM'}`
}

// A box has one border color, so a bevel is three boxes inside each other.
const Raised = ({ className = '', onClick, children }) => (
  <div className={`flex bg-[#c0c0c0] active:bg-[#a8a8a8] border-t border-l border-white ${className}`} onClick={onClick}>
    <div className="flex flex-1 min-w-0 border-b border-r border-black">
      <div className="flex flex-1 min-w-0 items-center gap-[1vh] px-[1.2vh] border-b border-r border-[#808080]">
        {children}
      </div>
    </div>
  </div>
)

const Sunken = ({ className = '', children }) => (
  <div className={`flex border-t border-l border-[#808080] ${className}`}>
    <div className="flex flex-1 min-w-0 border-b border-r border-white">
      <div className="flex flex-1 min-w-0 items-center gap-[1.2vh] px-[1.2vh]">{children}</div>
    </div>
  </div>
)

const Logo = () => (
  <svg viewBox="0 0 46 54" className="w-[4.2vh] h-[4.9vh]">
    <path fill="#111418" d="M0 0H46V5H5V30H0ZM26 49H41V32H46V54H26Z" />
    <rect x="7" y="36" width="12" height="11" rx="1.4" fill="#1c7c66" />
    <rect x="20" y="24" width="12" height="11" rx="1.4" fill="#8baa3a" />
    <rect x="33" y="12" width="12.5" height="11.5" rx="1.4" fill="#c8a247" />
  </svg>
)

const WindowIcon = () => (
  <svg viewBox="0 0 16 16" className="w-[3.4vh] h-[3.4vh]">
    <rect x="0.5" y="1.5" width="15" height="13" fill="#ffffff" stroke="#000000" />
    <rect x="1" y="2" width="14" height="3" fill="#000080" />
  </svg>
)

const PanelIcon = () => (
  <svg viewBox="0 0 16 16" className="w-[3.4vh] h-[3.4vh]">
    <rect x="0.5" y="0.5" width="15" height="15" fill="#ffffff" stroke="#000000" />
    <rect x="2" y="4" width="12" height="1" fill="#000000" />
    <rect x="2" y="11" width="12" height="1" fill="#000000" />
    <rect x="9" y="2" width="3" height="5" fill="#000080" />
    <rect x="4" y="9" width="3" height="5" fill="#008080" />
  </svg>
)

// Four bars for the Wi-Fi signal, nothing on a frame that cannot tell.
function Signal({ rssi }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -55 ? 4 : rssi >= -65 ? 3 : rssi >= -75 ? 2 : 1
  return (
    <div className="flex items-end gap-[0.3vh] h-[3vh]">
      {[1.2, 1.8, 2.4, 3].map((height, i) => (
        <div className={`w-[0.6vh] h-[${height}vh] ${i < level ? 'bg-black' : 'bg-[#808080]'}`} />
      ))}
    </div>
  )
}

function Battery({ percent }) {
  if (typeof percent !== 'number') return null
  return (
    <svg viewBox="0 0 22 12" className="w-[4.4vh] h-[2.4vh]">
      <rect x="0.5" y="0.5" width="18" height="11" fill="none" stroke="#000000" />
      <rect x="19" y="4" width="3" height="4" fill="#000000" />
      <rect x="2" y="2" width={(15 * percent) / 100} height="8" fill={percent > 15 ? '#000000' : '#800000'} />
    </svg>
  )
}

export function get(app) {
  const now = new Date()
  // The clock changes on the minute: nothing to draw until then.
  frameos.setNextSleep(60 - now.getSeconds())
  return (
    <div className="flex flex-col w-full h-full bg-[#008080] text-black text-[3.6vh]">
      <yield />
      <div className="bg-[#c0c0c0] border-t border-[#dfdfdf]">
        <div className="flex items-stretch h-[9vh] gap-[0.8vh] p-[0.7vh] border-t border-white">
          <Raised onClick={() => frameos.dispatch('sceneSwitcher')}>
            <Logo />
            <span className="font-bold">Start</span>
          </Raised>
          <Sunken className="flex-1 min-w-0 bg-[#e4e4e4]">
            <WindowIcon />
            <span className="flex-1 font-bold truncate">{app.frame.sceneName || 'FrameOS'}</span>
          </Sunken>
          <Raised onClick={() => frameos.dispatch('sceneSettings')}>
            <PanelIcon />
            {app.frame.width >= 640 ? <span>Control Panel</span> : null}
          </Raised>
          <Sunken>
            <Signal rssi={app.frame.wifiRssi} />
            <Battery percent={app.frame.batteryPercent} />
            <span className="whitespace-nowrap">{clock(now, on(app.state.twentyFourHour))}</span>
          </Sunken>
        </div>
      </div>
    </div>
  )
}
